def preserve_legacy_guest_links(apps, schema_editor):
    Event = apps.get_model('events', 'Event')
    Guest = apps.get_model('events', 'Guest')
    database = schema_editor.connection.alias

    Guest.objects.using(database).filter(event__status='draft').update(
        has_personal_link=False,
    )
    for event in Event.objects.using(database).exclude(status='draft').iterator():
        linked_count = Guest.objects.using(database).filter(
            event_id=event.pk,
            has_personal_link=True,
        ).count()
        event.paid_guest_count = linked_count
        event.paid_guest_quota = max(event.paid_guest_quota, linked_count)
        event.payment_status = 'succeeded' if linked_count else 'free'
        event.save(
            using=database,
            update_fields=[
                'paid_guest_count',
                'paid_guest_quota',
                'payment_status',
            ],
        )


